"""
MA Report API Server - 202608 (OneRecon Hackathon)
======================================================
Run: python ma_api_server.py
API: http://localhost:5000/api/ma/transactions?page=1&per_page=500

This server provides MA (Management Accounting) transaction data for period 202608.
Data is served exclusively through this API. No file access is provided.
"""
import zlib
import base64
import csv
import io
from flask import Flask, jsonify, request

app = Flask(__name__)

# --- Embedded Data (compressed) ---
_DATA = ""

def _load_data():
    compressed = base64.b64decode(_DATA)
    raw = zlib.decompress(compressed).decode("utf-8")
    reader = csv.DictReader(io.StringIO(raw))
    return list(reader)

# Pre-load into memory on startup
_db = _load_data()
print(f"  Loaded 202608: {len(_db)} records")

# --- API Endpoints ---

@app.route("/api/ma/health")
def health():
    return jsonify({"status": "ok", "service": "MA Report API", "period": "202608"})

@app.route("/api/ma/summary")
def summary():
    """Get summary stats."""
    total_amount = sum(float(r["Amount"]) for r in _db)
    return jsonify({
        "period": "202608",
        "total_records": len(_db),
        "total_amount": round(total_amount, 2),
        "avg_amount": round(total_amount / len(_db), 2) if _db else 0
    })

@app.route("/api/ma/transactions")
def transactions():
    """Paginated MA transactions."""
    page = int(request.args.get("page", 1))
    per_page = int(request.args.get("per_page", 500))

    if per_page < 1 or per_page > 5000:
        return jsonify({"error": "per_page must be between 1 and 5000"}), 400

    total = len(_db)
    total_pages = (total + per_page - 1) // per_page

    if page < 1 or page > total_pages:
        return jsonify({"error": "Page must be between 1 and " + str(total_pages)}), 400

    start = (page - 1) * per_page
    end = start + per_page
    data = _db[start:end]

    return jsonify({
        "data": data,
        "period": "202608",
        "total": total,
        "page": page,
        "per_page": per_page,
        "total_pages": total_pages
    })

@app.route("/api/ma/transactions/<txn_id>")
def get_transaction(txn_id):
    """Get a single transaction by ID."""
    for r in _db:
        if r["TransactionID"] == txn_id:
            return jsonify({"data": r})
    return jsonify({"error": "Transaction not found"}), 404

# --- Main ---
if __name__ == "__main__":
    print("=" * 50)
    print("  MA Report API Server - Period 202608")
    print("=" * 50)
    print("  Health:  http://localhost:5000/api/ma/health")
    print("  Summary: http://localhost:5000/api/ma/summary")
    print("  Data:    http://localhost:5000/api/ma/transactions?page=1&per_page=500")
    print("=" * 50)
    app.run(host="0.0.0.0", port=5000, debug=False)
